                                                  "properties",
                                                  "required",
                                                  "additionalProperties",
                                                  "items",
                                                  "minItems",
                                                  "maxItems",
                                                  "enum",
                                                  "const",
                                                  "anyOf",
                                                  "$defs",
                                                  "$ref",
                                                  "title",
                                                  "description",
                                                  "minimum",
                                                  "maximum",
                                                  "exclusiveMinimum",
                                                  "exclusiveMaximum",
                                                  "multipleOf",
                                                  "pattern",
                                                  "format",
                                                  "minLength",
                                                  "maxLength"};
  for (const auto& [key, value] : schema.members()) {
    if (!allowed.contains(key))
      Invalid("unsupported keyword: " + key);
